css:
/* Reference theme — mostly recipe variables now (simple), plus typography + shell-specific chrome. */
.shell {
  --morphism: 0;
  --surface-base: #fffaf2;
  --surface-fill: #fffaf2;
  --surface-sheen: linear-gradient(transparent, transparent);
  --surface-rim: none;
  --surface-filter: none;
  --surface-edge: #1c1a17;
  --control-base: #fffaf2;
  --control-fill: #fffaf2;
  --control-hover: #ffe0d3;
  --control-raised: #fffaf2;
  --control-border: #1c1a17;
  --control-border-hover: #e5432d;
  --control-inset: none;
  --control-button-shadow: 3px 3px 0 #1c1a17;
  --control-pressed-shadow: 1px 1px 0 #1c1a17;
  --control-popup-shadow: 6px 6px 0 #1c1a17;
  --control-recess: linear-gradient(transparent, transparent);
  --control-filter: none;
  --control-thumb: #1c1a17;
  --control-tint: #e5432d;
  --control-tint-ink: #fffaf5;
  /* Menubar / top bar */
  --menubar-island-height: 40px;
  --menubar-island-radius: 10px;
  --menubar-island-background: #1c1a17;
  --menubar-island-border: 2px solid #1c1a17;
  --menubar-island-shadow: 4px 4px 0 #e5432d;
  --menubar-island-backdrop: none;
  --menubar-item-radius: 6px;
  --menubar-item-hover: #e5432d;
  --menubar-font-size: 11px;
  /* Menus */
  --menu-background: #fffaf2;
  --menu-border: 2px solid #1c1a17;
  --menu-radius: 10px;
  --menu-shadow: 5px 5px 0 #1c1a17;
  --menu-backdrop: none;
  --menu-item-height: 32px;
  --menu-item-radius: 4px;
  --menu-item-hover: #ffe0d3;
  /* Groups */
  --group-background: #fffaf2;
  --group-border: 2px solid #1c1a17;
  --group-radius: 14px;
  --group-shadow: 4px 4px 0 #1c1a17;
  --group-row-height: 62px;
  --group-row-padding: 14px 18px;
  /* Window chrome */
  --window-titlebar-height: 46px;
  --window-titlebar-padding: 0 14px 0 18px;
  --window-titlebar-border: 2px solid #1c1a17;
  --window-control-radius: 4px;
  /* Topbar islands + toolbar */
  --topbar-island-height: 40px;
  --topbar-island-radius: 10px;
  --topbar-island-background: #1c1a17;
  --topbar-island-border: 2px solid #1c1a17;
  --topbar-island-shadow: 4px 4px 0 #e5432d;
  --topbar-island-backdrop: none;
  --topbar-mode-radius: 6px;
  --topbar-button-radius: 4px;
  --toolbar-radius: 10px;
  --toolbar-background: #fffaf2;
  --toolbar-border: 2px solid #1c1a17;
  --toolbar-shadow: 3px 3px 0 #1c1a17;
  --toolbar-backdrop: none;
  /* Chips, badges, notices, trays */
  --chip-radius: 6px;
  --chip-border: 2px solid #1c1a17;
  --chip-background: #fffaf2;
  --chip-shadow: 2px 2px 0 #1c1a17;
  --badge-radius: 6px;
  --badge-border: 2px solid #1c1a17;
  --badge-background: #fffaf2;
  --notice-radius: 10px;
  --notice-border: 2px solid #1c1a17;
  --notice-background: #fffaf2;
  --tray-radius: 10px;
  --tray-background: #fffaf2;
  /* Switch + choice */
  --switch-width: 46px;
  --switch-height: 26px;
  --switch-thumb-size: 18px;
  --switch-pad: 3px;
  --switch-border-width: 2px;
  --switch-border-color: #1c1a17;
  --switch-radius: 5px;
  --switch-background: #fffaf2;
  --switch-background-checked: #1c1a17;
  --switch-border-checked: #1c1a17;
  --switch-thumb: #1c1a17;
  --switch-thumb-checked: #fffaf2;
  --switch-thumb-radius: 3px;
  --switch-thumb-shadow: 1px 1px 0 #1c1a17;
  --switch-thumb-transition: transform 90ms steps(2, end);
  --switch-active-scale: 1.15;
  --choice-radius: 4px;
  --choice-border: 2px solid #1c1a17;
  --choice-background: #fffaf2;
  --choice-checked-background: #e5432d;
  --choice-checked-border: #1c1a17;
  --choice-mark: #fffaf5;
}
/* Typography */
.shell :is(h1, h2, h3, .titlebar-title) { font-family: var(--rumahl-ui-typography-display), system-ui, sans-serif; font-weight: 700; letter-spacing: -0.02em; }
.shell :is(.section-title, .rumahl-settings__section-title, .rumahl-settings__eyebrow, .settings-page-heading > span) { text-transform: uppercase; letter-spacing: 0.14em; color: #e5432d; font-weight: 700; }
/* Shell-specific chrome (topbar + taskbar) */
.shell .topbar__island, .shell .menubar { background: #1c1a17 !important; color: #fffaf2 !important; border: 2px solid #1c1a17 !important; border-radius: 10px !important; box-shadow: 4px 4px 0 #e5432d !important; }
.shell :is(.menubar__item, .menubar__menu, .topbar__button) { color: #fffaf2 !important; text-transform: uppercase; letter-spacing: 0.08em; font-size: 11px; }
.shell :is(.menubar__item, .topbar__button):hover { background: #e5432d !important; color: #fffaf5 !important; }
.shell .taskbar { background: #1c1a17 !important; color: #fffaf2 !important; border-radius: 12px !important; border: 2px solid #1c1a17 !important; box-shadow: 5px 5px 0 #e5432d !important; }
.shell .taskbar :is(button, a) { color: #fffaf2 !important; }
/* Controls that still need direct shaping */
.shell :is(.btn, button, input, select, textarea) { border-radius: 6px !important; }
.shell :is(.btn, button, input, select, textarea, .rumahl-button-group, .rumahl-input, .rumahl-select) { border: 2px solid #1c1a17 !important; background: #fffaf2 !important; box-shadow: 3px 3px 0 #1c1a17 !important; color: #1c1a17 !important; }
.shell :is(.btn, button):hover { background: #ffe0d3 !important; }
.shell .display-settings :is(button:not(.theme-swatch), select) { border-radius: 6px !important; border: 2px solid #1c1a17 !important; box-shadow: 3px 3px 0 #1c1a17 !important; background: #fffaf2 !important; color: #1c1a17 !important; }
.shell .segmented { background: #fffaf2 !important; border: 2px solid #1c1a17 !important; box-shadow: 3px 3px 0 #1c1a17 !important; border-radius: 6px !important; overflow: hidden; }
.shell .segmented button { border: 0 !important; border-radius: 0 !important; box-shadow: none !important; background: transparent !important; }
.shell .segmented button[aria-pressed='true'] { background: #1c1a17 !important; color: #fffaf2 !important; }
.shell :is(.appearance-switch input, input[role='switch']) { width: var(--switch-width) !important; height: var(--switch-height) !important; border: var(--switch-border-width) solid var(--switch-border-color) !important; border-radius: var(--switch-radius) !important; background: var(--switch-background) !important; box-shadow: none !important; backdrop-filter: none !important; }
.shell :is(.appearance-switch input, input[role='switch']):checked { background: var(--switch-background-checked) !important; border-color: var(--switch-border-checked) !important; }
.shell :is(.appearance-switch input, input[role='switch'])::before { background: var(--switch-thumb) !important; border-radius: var(--switch-thumb-radius) !important; box-shadow: var(--switch-thumb-shadow) !important; transition: var(--switch-thumb-transition) !important; }
.shell :is(.appearance-switch input, input[role='switch']):checked::before { background: var(--switch-thumb-checked) !important; }
.shell :is(.appearance-switch input, input[role='switch']):active::before { scale: var(--switch-active-scale) !important; }
.shell :focus-visible { outline: 3px solid #e5432d !important; outline-offset: 2px; }
.shell ::selection { background: #e5432d; color: #fffaf5; }
